#!/usr/bin/env python3
"""Build every generated file from brainstorm.yaml.

Usage:
    python3 scripts/build.py                     # regenerate docs, mind maps and README sections
    python3 scripts/build.py --artifact OUT.html # also write the page fragment used for the claude.ai artifact

Outputs (all generated, do not edit by hand):
    docs/problems.md, docs/ideas.md, docs/mindmaps/track-{1..4}.md,
    mindmap/mindmap.md, mindmap/index.html, and the marked sections of README.md.
"""
import argparse
import html
import json
import re
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parent.parent
LETTERS = "abcde"
GEN = "<!-- Generated by scripts/build.py from brainstorm.yaml. Edit the YAML, not this file. -->"
EXAMPLE_MARK = "◇"
PICK_MARK = "★"


# ---------- load and validate ----------

def load():
    data = yaml.safe_load((ROOT / "brainstorm.yaml").read_text(encoding="utf-8"))
    for t_i, track in enumerate(data["tracks"], start=1):
        track["key"] = f"t{t_i}"
        track["num"] = t_i
        for prob in track["problems"]:
            for i, idea in enumerate(prob["ideas"]):
                idea["id"] = prob["id"] + LETTERS[i]
    validate(data)
    picks = {p["idea"] for p in data["top_picks"]}
    for _, _, idea in iter_ideas(data):
        idea["pick"] = idea["id"] in picks
    return data


def iter_problems(data):
    for track in data["tracks"]:
        for prob in track["problems"]:
            yield track, prob


def iter_ideas(data):
    for track, prob in iter_problems(data):
        for idea in prob["ideas"]:
            yield track, prob, idea


def validate(data):
    errors = []
    probs = list(iter_problems(data))
    if len(data["tracks"]) != 4:
        errors.append(f"expected 4 tracks, found {len(data['tracks'])}")
    if len(probs) != 16:
        errors.append(f"expected 16 problems, found {len(probs)}")
    prob_ids = [p["id"] for _, p in probs]
    if len(set(prob_ids)) != len(prob_ids):
        errors.append("duplicate problem ids")
    for _, prob in probs:
        n = len(prob["ideas"])
        if not 3 <= n <= 5:
            errors.append(f"{prob['id']}: {n} ideas (need 3-5)")
        for key in ("title", "problem"):
            if not prob.get(key):
                errors.append(f"{prob['id']}: missing {key}")
    for _, _, idea in iter_ideas(data):
        where = idea["id"]
        for key in ("title", "what", "data", "effort", "rl"):
            if not idea.get(key):
                errors.append(f"{where}: missing {key}")
        if idea.get("effort") not in data["effort"]:
            errors.append(f"{where}: effort {idea.get('effort')!r} not in {list(data['effort'])}")
        rl = idea.get("rl") or {}
        if rl.get("pattern") not in data["rl_patterns"]:
            errors.append(f"{where}: unknown RL pattern {rl.get('pattern')!r}")
        for key in ("title", "what"):
            if not rl.get(key):
                errors.append(f"{where}: RL version missing {key}")
    idea_ids = {idea["id"] for _, _, idea in iter_ideas(data)}
    for theme in data["themes"]:
        for ref in theme["problems"]:
            if ref not in prob_ids:
                errors.append(f"theme {theme['name']!r}: unknown problem {ref}")
    for pick in data["top_picks"]:
        if pick["idea"] not in idea_ids:
            errors.append(f"top pick: unknown idea {pick['idea']}")
        for key in ("why", "kill"):
            if not pick.get(key):
                errors.append(f"top pick {pick['idea']}: missing {key}")
    if errors:
        sys.exit("brainstorm.yaml failed validation:\n  " + "\n  ".join(errors))


def counts(data):
    n_ideas = sum(1 for _ in iter_ideas(data))
    return len(list(iter_problems(data))), n_ideas


def idea_lookup(data):
    return {idea["id"]: (track, prob, idea) for track, prob, idea in iter_ideas(data)}


def markers(idea):
    out = ""
    if idea.get("sprint_example"):
        out += " " + EXAMPLE_MARK
    if idea.get("pick"):
        out += " " + PICK_MARK
    return out


def clean(text):
    return " ".join(str(text).split())


# ---------- markdown docs ----------

def build_problems(data):
    lines = [GEN, "", "# Key problems", ""]
    n_p, _ = counts(data)
    lines += [
        f"{n_p} problems, four per track, rephrased from the challenges each track lists on the sprint page. "
        "Ideas for each one are in [ideas.md](ideas.md). The interactive map is "
        "[mindmap/index.html](../mindmap/index.html).",
        "",
    ]
    for track in data["tracks"]:
        lines += [f"## Track {track['num']} · {track['name']}", "", f"*{clean(track['question'])}*", ""]
        for prob in track["problems"]:
            lines.append(f"- **{prob['id']} {prob['title']}.** {clean(prob['problem'])}")
        lines.append("")
    lines += ["## Cross-cutting themes", ""]
    for theme in data["themes"]:
        refs = ", ".join(theme["problems"])
        lines.append(f"- **{theme['name']}.** {clean(theme['what'])} ({refs})")
    lines.append("")
    return "\n".join(lines)


def build_ideas(data):
    n_p, n_i = counts(data)
    pats = data["rl_patterns"]
    lines = [GEN, "", "# Ideas and RL versions", ""]
    lines += [
        f"{n_i} ideas for {n_p} problems. Every idea has an RL version underneath it. "
        f"{EXAMPLE_MARK} marks an idea the sprint page already lists as an example; many teams will pick those, "
        f"so they need a new angle to score 4–5 on innovation. {PICK_MARK} marks a top pick (see the README).",
        "",
        "**Weekend effort.** " + "; ".join(f"`{k}` {v}" for k, v in data["effort"].items()) + ".",
        "",
        "**RL patterns used below.**",
        "",
    ]
    for p in pats.values():
        lines.append(f"- **{p['name']}.** {clean(p['what'])}")
    lines.append("")
    for track in data["tracks"]:
        lines += [f"## Track {track['num']} · {track['name']}", "", f"*{clean(track['question'])}*", ""]
        for prob in track["problems"]:
            lines += [f"### {prob['id']} {prob['title']}", "", clean(prob["problem"]), ""]
            for idea in prob["ideas"]:
                rl = idea["rl"]
                lines += [
                    f"#### {idea['id']} {idea['title']} · `{idea['effort']}`{markers(idea)}",
                    "",
                    clean(idea["what"]),
                    "",
                    f"*Data and tools:* {clean(idea['data'])}",
                    "",
                    f"> **RL version ({pats[rl['pattern']]['name']}): {rl['title']}.** {clean(rl['what'])}",
                    "",
                ]
    return "\n".join(lines)


# ---------- mermaid ----------

def mm_label(text, limit=60):
    text = clean(text)
    text = text.replace("&", "and").replace("'", "\u2019")
    text = re.sub(r"[()\[\]{}\"'`<>#;|]", "", text)
    if len(text) > limit:
        text = text[: limit - 1].rstrip() + "…"
    return text


def mm_id(text):
    return re.sub(r"[^A-Za-z0-9]", "", text)


def build_track_mermaid(data, track):
    lines = [
        GEN,
        "",
        f"# Track {track['num']} · {track['name']}",
        "",
        f"*{clean(track['question'])}*",
        "",
        "Problems are boxes, ideas are rounded, RL versions are hexagons. Full text is in "
        "[docs/ideas.md](../ideas.md). The interactive map is [mindmap/index.html](../../mindmap/index.html).",
        "",
        "```mermaid",
        "mindmap",
        f"  root((Track {track['num']}))",
    ]
    for prob in track["problems"]:
        lines.append(f"    {mm_id('p' + prob['id'])}[{mm_label(prob['id'] + ' ' + prob['title'])}]")
        for idea in prob["ideas"]:
            lines.append(f"      {mm_id('i' + idea['id'])}({mm_label(idea['id'] + ' ' + idea['title'])})")
            lines.append(f"        {mm_id('r' + idea['id'])}{{{{{mm_label('RL · ' + idea['rl']['title'])}}}}}")
    lines += ["```", ""]
    return "\n".join(lines)


def build_overview_mermaid(data):
    lines = ["```mermaid", "mindmap", "  root((AI x Epistemics))"]
    for track in data["tracks"]:
        lines.append(f"    {mm_id(track['id'])}[{mm_label('Track ' + str(track['num']) + ' ' + track['name'])}]")
        for prob in track["problems"]:
            lines.append(f"      {mm_id('p' + prob['id'])}({mm_label(prob['id'] + ' ' + prob['title'])})")
    lines.append("```")
    return "\n".join(lines)


# ---------- markmap ----------

def build_markmap_md(data):
    pats = data["rl_patterns"]
    lines = [
        "---",
        "title: AI x Epistemics sprint brainstorm",
        "markmap:",
        "  colorFreezeLevel: 2",
        "  initialExpandLevel: 3",
        "  maxWidth: 360",
        "---",
        "",
        GEN,
        "",
        "# AI x Epistemics sprint",
        "",
        "## Top picks",
    ]
    look = idea_lookup(data)
    for pick in data["top_picks"]:
        _, _, idea = look[pick["idea"]]
        lines.append(f"- **{idea['id']} {idea['title']}** {PICK_MARK}: {clean(pick['why'])}")
        lines.append(f"  - *Kill test:* {clean(pick['kill'])}")
    for track in data["tracks"]:
        lines += ["", f"## Track {track['num']} · {track['name']}"]
        for prob in track["problems"]:
            lines.append(f"### {prob['id']} {prob['title']}")
            for idea in prob["ideas"]:
                rl = idea["rl"]
                lines.append(f"- **{idea['id']} {idea['title']}** `{idea['effort']}`{markers(idea)}: {clean(idea['what'])}")
                lines.append(f"  - *RL · {pats[rl['pattern']]['name']}:* **{rl['title']}.** {clean(rl['what'])}")
    lines += ["", "## Cross-cutting themes"]
    for theme in data["themes"]:
        lines.append(f"- **{theme['name']}.** {clean(theme['what'])} ({', '.join(theme['problems'])})")
    lines += ["", "## RL patterns"]
    for p in pats.values():
        lines.append(f"- **{p['name']}.** {clean(p['what'])}")
    lines.append("")
    return "\n".join(lines)


def esc(text):
    return html.escape(clean(text), quote=False)


def node(content, color, key, children=(), aux=False):
    payload = {"c": color, "k": key}
    if aux:
        payload["aux"] = 1
    return {
        "content": f'<span class="m-n" data-k="{key}">{content}</span>',
        "payload": payload,
        "children": list(children),
    }


def flags_html(idea):
    out = ""
    if idea.get("sprint_example"):
        out += f' <span class="m-ex" title="Listed as an example on the sprint page">{EXAMPLE_MARK}</span>'
    if idea.get("pick"):
        out += f' <span class="m-star" title="Top pick">{PICK_MARK}</span>'
    return out


def build_tree(data):
    """Short labels only; the full text lives in the detail panel (build_details)."""
    look = idea_lookup(data)
    picks = []
    for pick in data["top_picks"]:
        _, _, idea = look[pick["idea"]]
        picks.append(node(
            f'<span class="m-id">{idea["id"]}</span> {esc(idea["title"])} <span class="m-star">{PICK_MARK}</span>',
            "pick", "pick-" + idea["id"],
        ))
    tracks = []
    for track in data["tracks"]:
        c = track["key"]
        probs = []
        for prob in track["problems"]:
            ideas = []
            for idea in prob["ideas"]:
                rl_node = node(f'<span class="m-rl">RL</span> {esc(idea["rl"]["title"])}', c, idea["id"] + "-rl")
                ideas.append(node(
                    f'<span class="m-id">{idea["id"]}</span> {esc(idea["title"])} '
                    f'<span class="m-eff" title="Weekend effort">{idea["effort"]}</span>{flags_html(idea)}',
                    c, idea["id"], [rl_node],
                ))
            probs.append(node(f'<span class="m-id">{prob["id"]}</span> <b>{esc(prob["title"])}</b>', c, prob["id"], ideas))
        tracks.append(node(
            f'<span class="m-id">Track {track["num"]}</span> <span class="m-track">{esc(track["name"])}</span>',
            c, track["id"], probs,
        ))
    themes = [node(esc(t["name"]), "theme", f"theme-{i}") for i, t in enumerate(data["themes"], start=1)]
    patterns = [node(esc(p["name"]), "rl", f"pat-{k}") for k, p in data["rl_patterns"].items()]
    return node(
        '<span class="m-root">AI x Epistemics sprint</span>', "root", "root",
        [node('<span class="m-branch">Top picks</span>', "pick", "picks", picks)]
        + tracks
        + [node('<span class="m-branch">Cross-cutting themes</span>', "theme", "themes", themes, aux=True),
           node('<span class="m-branch">RL patterns</span>', "rl", "patterns", patterns, aux=True)],
    )


def ref(key, label):
    return f'<button type="button" class="ref" data-go="{key}">{label}</button>'


def kicker(text, extra=""):
    return f'<p class="p-kicker{extra}">{text}</p>'


def eff_chip(data, effort):
    return f'<span class="chip"><span class="m-eff">{effort}</span> {esc(data["effort"][effort])}</span>'


def build_details(data):
    """Panel HTML for every node key. All text is escaped here; the page only injects it."""
    pats, look = data["rl_patterns"], idea_lookup(data)
    n_p, n_i = counts(data)
    themes_by_prob, ideas_by_pat = {}, {k: [] for k in pats}
    for i, t in enumerate(data["themes"], start=1):
        for pid in t["problems"]:
            themes_by_prob.setdefault(pid, []).append((i, t))
    for _, _, idea in iter_ideas(data):
        ideas_by_pat[idea["rl"]["pattern"]].append(idea)
    d = {}

    tracks_list = ""
    for t in data["tracks"]:
        label = "Track {} · {}".format(t["num"], esc(t["name"]))
        tracks_list += f'<li>{ref(t["id"], label)}<span class="p-small">{esc(t["question"])}</span></li>'
    d["root"] = (
        kicker("Overview")
        + "<h2>AI x Epistemics sprint</h2>"
        + f"<p>The key problems in all four tracks, {n_p} in total, with 3–5 ideas or experiments for each "
          f"({n_i} ideas) and an RL version of every idea. Start with the top picks, or open a track.</p>"
        + f'<p class="p-links">{ref("picks", f"{PICK_MARK} Top picks")} {ref("themes", "Cross-cutting themes")} {ref("patterns", "RL patterns")}</p>'
        + f'<ul class="p-list">{tracks_list}</ul>'
        + "<h3>Markers</h3><dl class=\"p-dl\">"
        + "".join(f'<dt><span class="m-eff">{k}</span></dt><dd>{esc(v)}</dd>' for k, v in data["effort"].items())
        + f'<dt><span class="m-ex">{EXAMPLE_MARK}</span></dt><dd>Listed as an example on the sprint page. Many teams '
          f'will pick these, so they need a new angle to score 4–5 on innovation.</dd>'
        + f'<dt><span class="m-star">{PICK_MARK}</span></dt><dd>Top pick</dd>'
        + '<dt><span class="m-rl">RL</span></dt><dd>The RL version of the idea it hangs from.</dd></dl>'
        + f'<p class="p-small">Click a label to read it here. Click a dot to open or close its branch. '
          f'<a href="{esc(data["meta"]["url"])}" target="_blank" rel="noopener">Sprint page</a></p>'
    )

    d["picks"] = (
        kicker("Top picks") + "<h2>Five ideas to start from</h2>"
        + "<p>Ranked by novelty, fit to the judging rubric, and what can be finished by Sunday 23:59 AoE.</p>"
        + '<ol class="p-list">'
        + "".join(
            f'<li>{ref("pick-" + p["idea"], p["idea"] + " " + esc(look[p["idea"]][2]["title"]))}</li>'
            for p in data["top_picks"]
        )
        + "</ol>"
    )
    for rank, p in enumerate(data["top_picks"], start=1):
        track, prob, idea = look[p["idea"]]
        d["pick-" + idea["id"]] = (
            kicker(f"Top pick {rank} of {len(data['top_picks'])} · Track {track['num']}", " pick")
            + f"<h2>{idea['id']} {esc(idea['title'])}</h2>"
            + f"<p>{esc(p['why'])}</p>"
            + f'<section class="p-box"><p class="p-kicker kill">Kill test</p><p>{esc(p["kill"])}</p></section>'
            + f'<p>{ref(idea["id"], "Open the idea and its RL version")}</p>'
        )

    for track in data["tracks"]:
        d[track["id"]] = (
            kicker(f"Track {track['num']}") + f"<h2>{esc(track['name'])}</h2>"
            + f'<p class="p-q">{esc(track["question"])}</p><h3>Problems</h3><ul class="p-list">'
            + "".join(
                f'<li>{ref(pr["id"], pr["id"] + " " + esc(pr["title"]))}<span class="p-small">{esc(pr["problem"])}</span></li>'
                for pr in track["problems"]
            )
            + "</ul>"
        )
        for prob in track["problems"]:
            themes = themes_by_prob.get(prob["id"], [])
            d[prob["id"]] = (
                kicker(f"Problem · Track {track['num']} · {esc(track['name'])}")
                + f"<h2>{prob['id']} {esc(prob['title'])}</h2><p>{esc(prob['problem'])}</p><h3>Ideas</h3>"
                + '<ul class="p-list">'
                + "".join(
                    f'<li>{ref(i["id"], i["id"] + " " + esc(i["title"]))} <span class="m-eff">{i["effort"]}</span>'
                    f'{flags_html(i)}<span class="p-small"><span class="m-rl">RL</span> {esc(i["rl"]["title"])}</span></li>'
                    for i in prob["ideas"]
                )
                + "</ul>"
                + (
                    "<h3>Shared themes</h3><p>" + " ".join(ref(f"theme-{n}", esc(t["name"])) for n, t in themes) + "</p>"
                    if themes else ""
                )
            )
            for idea in prob["ideas"]:
                rl, pat = idea["rl"], pats[idea["rl"]["pattern"]]
                chips = eff_chip(data, idea["effort"])
                if idea.get("sprint_example"):
                    chips += f'<span class="chip"><span class="m-ex">{EXAMPLE_MARK}</span> sprint-page example</span>'
                if idea.get("pick"):
                    chips += f'<span class="chip"><span class="m-star">{PICK_MARK}</span> top pick</span>'
                rl_body = (
                    f"<h3>{esc(rl['title'])}</h3><p>{esc(rl['what'])}</p>"
                    f'<p class="p-small"><b>{esc(pat["name"])}:</b> {esc(pat["what"])}</p>'
                )
                d[idea["id"]] = (
                    kicker(f"Idea · {prob['id']} {esc(prob['title'])}")
                    + f"<h2>{idea['id']} {esc(idea['title'])}</h2>"
                    + f'<p class="p-chips">{chips}</p><p>{esc(idea["what"])}</p>'
                    + f'<p class="p-small"><b>Data and tools:</b> {esc(idea["data"])}</p>'
                    + f'<section class="p-box rl">{kicker("RL version · " + esc(pat["name"]), " rl")}{rl_body}</section>'
                    + f'<p>{ref(prob["id"], "Back to " + prob["id"] + " " + esc(prob["title"]))}</p>'
                )
                d[idea["id"] + "-rl"] = (
                    kicker(f"RL version of {idea['id']} · {esc(pat['name'])}", " rl")
                    + f"<h2>{esc(rl['title'])}</h2><p>{esc(rl['what'])}</p>"
                    + f'<p class="p-small"><b>{esc(pat["name"])}:</b> {esc(pat["what"])}</p>'
                    + f'<section class="p-box">{kicker("Base idea")}<h3>{idea["id"]} {esc(idea["title"])}</h3>'
                    + f'<p>{esc(idea["what"])}</p><p>{ref(idea["id"], "Open the base idea")}</p></section>'
                )

    d["themes"] = (
        kicker("Cross-cutting themes") + "<h2>Problems that share a root</h2>"
        + "<p>The same few difficulties show up across tracks. A project that solves one of them for one problem "
          "often transfers to the others.</p><ul class=\"p-list\">"
        + "".join(
            f'<li>{ref(f"theme-{i}", esc(t["name"]))}<span class="p-small">{esc(t["what"])}</span></li>'
            for i, t in enumerate(data["themes"], start=1)
        )
        + "</ul>"
    )
    for i, t in enumerate(data["themes"], start=1):
        d[f"theme-{i}"] = (
            kicker("Cross-cutting theme", " theme") + f"<h2>{esc(t['name'])}</h2><p>{esc(t['what'])}</p>"
            + '<h3>Problems</h3><ul class="p-list">'
            + "".join(
                f'<li>{ref(pid, pid + " " + esc(next(pr for _, pr in iter_problems(data) if pr["id"] == pid)["title"]))}</li>'
                for pid in t["problems"]
            )
            + "</ul>"
        )

    d["patterns"] = (
        kicker("RL patterns", " rl") + f"<h2>{len(pats)} ways to add RL</h2>"
        + "<p>Every idea's RL version uses one of these. Most come in two sizes: a cheap one (a bandit or best-of-n "
          "over API calls) that fits the deadline, and a full one (GRPO on a small open model) as a stretch goal.</p>"
        + '<ul class="p-list">'
        + "".join(
            f'<li>{ref("pat-" + k, esc(p["name"]))} <span class="p-small">used by {len(ideas_by_pat[k])} ideas</span></li>'
            for k, p in pats.items()
        )
        + "</ul>"
    )
    for k, p in pats.items():
        d["pat-" + k] = (
            kicker("RL pattern", " rl") + f"<h2>{esc(p['name'])}</h2><p>{esc(p['what'])}</p>"
            + f'<h3>Used by {len(ideas_by_pat[k])} ideas</h3><ul class="p-list">'
            + "".join(
                f'<li>{ref(i["id"] + "-rl", i["id"] + " " + esc(i["rl"]["title"]))}</li>' for i in ideas_by_pat[k]
            )
            + "</ul>"
        )
    return d


def to_json(obj):
    return json.dumps(obj, ensure_ascii=False, separators=(",", ":")).replace("</", "<\\/")


def build_page(data):
    n_p, n_i = counts(data)
    tree = build_tree(data)
    details = build_details(data)
    keys = []

    def walk(n):
        keys.append(n["payload"]["k"])
        for c in n["children"]:
            walk(c)

    walk(tree)
    missing = [k for k in keys if k not in details]
    if missing or len(set(keys)) != len(keys):
        sys.exit(f"panel details missing for {missing} or duplicate node keys")
    stats = f"{n_p} problems from the four tracks, {n_i} ideas, and an RL version of every idea."
    template = (ROOT / "scripts" / "page.html").read_text(encoding="utf-8")
    return (
        template.replace("__TREE__", to_json(tree))
        .replace("__DETAILS__", to_json(details))
        .replace("__STATS__", html.escape(stats, quote=False))
    )


def standalone(fragment):
    head = (
        "<!doctype html>\n<html lang=\"en\">\n<meta charset=\"utf-8\">\n"
        "<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n"
        f"{GEN}\n"
    )
    return head + fragment


# ---------- README sections ----------

def build_top_picks(data):
    look = idea_lookup(data)
    lines = []
    for i, pick in enumerate(data["top_picks"], start=1):
        track, prob, idea = look[pick["idea"]]
        pats = data["rl_patterns"]
        lines += [
            f"{i}. **{idea['id']} {idea['title']}** (`{idea['effort']}`, Track {track['num']}, {prob['title']}). "
            f"RL version: *{idea['rl']['title']}* ({pats[idea['rl']['pattern']]['name']}).",
            f"   - *Why:* {clean(pick['why'])}",
            f"   - *Kill test:* {clean(pick['kill'])}",
        ]
    return "\n".join(lines)


def replace_section(text, name, body):
    start, end = f"<!-- BEGIN:{name} -->", f"<!-- END:{name} -->"
    pattern = re.compile(re.escape(start) + r".*?" + re.escape(end), re.S)
    if not pattern.search(text):
        sys.exit(f"README.md is missing the {start} ... {end} markers")
    return pattern.sub(lambda _: f"{start}\n{body}\n{end}", text)


# ---------- main ----------

def write(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
    print(f"wrote {path.relative_to(ROOT) if path.is_relative_to(ROOT) else path}")


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--artifact", type=Path, help="also write the bare page fragment here (for claude.ai artifacts)")
    args = ap.parse_args()

    data = load()
    write(ROOT / "docs" / "problems.md", build_problems(data))
    write(ROOT / "docs" / "ideas.md", build_ideas(data))
    for track in data["tracks"]:
        write(ROOT / "docs" / "mindmaps" / f"track-{track['num']}.md", build_track_mermaid(data, track))
    write(ROOT / "mindmap" / "mindmap.md", build_markmap_md(data))
    fragment = build_page(data)
    write(ROOT / "mindmap" / "index.html", standalone(fragment))
    if args.artifact:
        write(args.artifact, fragment)

    readme = ROOT / "README.md"
    text = readme.read_text(encoding="utf-8")
    text = replace_section(text, "overview", build_overview_mermaid(data))
    text = replace_section(text, "top-picks", build_top_picks(data))
    write(readme, text)

    n_p, n_i = counts(data)
    print(f"ok: {n_p} problems, {n_i} ideas, {n_i} RL versions, {len(data['top_picks'])} top picks")


if __name__ == "__main__":
    main()
